<?php
require_once __DIR__.'/estoque_service.php';exigirPermissao('movimentacoes');
$from=(string)($_GET['de']??'');$to=(string)($_GET['ate']??'');$pid=(string)($_GET['ferramenta']??'');$rows=[];$error='';
try{filtrarDatas($from,$to);$w=[];$a=[];if($from){$w[]='m.criado_em>=?';$a[]=$from.' 00:00:00';}if($to){$w[]='m.criado_em<?';$a[]=(new DateTimeImmutable($to))->modify('+1 day')->format('Y-m-d');}if($pid!==''){if(!ctype_digit($pid)||(int)$pid<1)throw new RuntimeException('ID inválido.');$w[]='m.codigo_ferramenta=?';$a[]=(int)$pid;}
$rows=query('SELECT m.id,m.criado_em,m.codigo_ferramenta,m.ferramenta_nome,m.tipo,m.quantidade,m.saldo_anterior,m.saldo_posterior,COALESCE(u.nome,\'Implantação\') autor,m.referencia,m.motivo FROM movimentacoes_estoque m LEFT JOIN usuarios u ON u.id=m.usuario_id'.($w?' WHERE '.implode(' AND ',$w):'').' ORDER BY m.id DESC LIMIT 500',$a)->fetchAll(PDO::FETCH_NUM);
}catch(RuntimeException $e){$error=$e instanceof PDOException?'Importe atualizar_operacoes.sql antes de usar este módulo.':$e->getMessage();}
$cols=['Nº','Data','ID ferramenta','Ferramenta','Operação','Variação','Antes','Depois','Responsável','Referência','Motivo'];
if(($_GET['exportar']??'')==='csv'&&!$error){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="movimentacoes.csv"');$f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,$cols,';');foreach($rows as $row)fputcsv($f,array_map(fn($v)=>preg_match('/^[\s]*[=+@-]/u',(string)$v)?"'".$v:$v,$row),';');exit;}
page('Histórico do estoque');?>
<section class="card no-print"><form class="form-grid" method="get"><input type="hidden" name="p" value="movimentacoes"><label>ID da ferramenta<input name="ferramenta" inputmode="numeric" value="<?=e($pid)?>"></label><label>De<input type="date" name="de" value="<?=e($from)?>"></label><label>Até<input type="date" name="ate" value="<?=e($to)?>"></label><div class="form-footer"><button>Consultar</button><button class="secondary" name="exportar" value="csv">Exportar CSV</button><button type="button" class="secondary" id="print-report">Imprimir / salvar PDF</button></div></form></section>
<?php if($error):?><p class="notice"><?=e($error)?></p><?php endif;?><section class="card"><p>Últimas 500 movimentações do filtro. O saldo de implantação é o ponto inicial; operações anteriores à atualização não são reconstruídas. Devoluções sem reposição têm variação zero e permanecem fora do estoque disponível.</p><div class="table-wrap"><table><thead><tr><?php foreach($cols as $v):?><th><?=e($v)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=e($v)?></td><?php endforeach;?></tr><?php endforeach;if(!$rows)emptyRow(count($cols));?></tbody></table></div></section><?php endpage();
